import { useState, type ReactNode } from "react";

type Page = "dashboard" | "classes" | "class" | "practice" | "library" | "progress" | "builder" | "quiz" | "results" | "auth" | "materials" | "test-management" | "statistics" | "student";
type Role = "student" | "teacher";
type IconName = "home" | "classes" | "tests" | "chart" | "bell" | "search" | "plus" | "arrow" | "clock" | "check" | "menu" | "flame" | "book" | "play" | "users" | "spark" | "sun" | "moon" | "upload" | "file";

const paths: Record<IconName, ReactNode> = {
  home: <><path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9M9 20v-6h6v6"/></>,
  classes: <><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H6.5A2.5 2.5 0 0 0 4 20.5z"/><path d="M4 5.5v15M8 7h8"/></>,
  tests: <><path d="M9 5h10v16H5V5h4"/><path d="M9 3h6v4H9zM8 12l1.5 1.5L12 11M8 17h7"/></>,
  chart: <><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></>,
  bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></>,
  search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,
  plus: <path d="M12 5v14M5 12h14"/>, arrow: <><path d="M5 12h14M14 7l5 5-5 5"/></>,
  clock: <><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>, check: <path d="m5 12 4 4L19 6"/>,
  menu: <path d="M4 7h16M4 12h16M4 17h16"/>, flame: <path d="M13.5 2.5c.7 4-2.1 5.2-2.1 8.1 0 1.1.7 1.9 1.7 1.9 1.5 0 2.4-1.7 2.2-3.2 2.1 1.6 3.4 4 3.2 6.3-.3 3.5-3 5.9-6.5 5.9s-6.5-2.6-6.5-6.2c0-3.1 1.8-5.3 4.4-7.5-.1 2.3.8 3.5 1.7 3.8-.4-3.1.2-6.7 1.7-9.1Z"/>,
  book: <><path d="M3 5a4 4 0 0 1 4-2h5v17H7a4 4 0 0 0-4 2zM21 5a4 4 0 0 0-4-2h-5v17h5a4 4 0 0 1 4 2z"/></>,
  play: <><circle cx="12" cy="12" r="9"/><path d="m10 8 6 4-6 4z"/></>, users: <><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/></>,
  spark: <><path d="m12 3 1.2 3.8L17 8l-3.8 1.2L12 13l-1.2-3.8L7 8l3.8-1.2zM19 15l.7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7z"/></>,
  sun: <><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></>,
  moon: <path d="M20 15.5A8 8 0 0 1 8.5 4 8.5 8.5 0 1 0 20 15.5Z"/>,
  upload: <><path d="M12 16V4M7 9l5-5 5 5"/><path d="M4 15v5h16v-5"/></>,
  file: <><path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5M9 13h6M9 17h6"/></>,
};

function Icon({ name, className = "size-5" }: { name: IconName; className?: string }) {
  return <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

const Button = ({ children, onClick, secondary = false, className = "", disabled = false }: { children: ReactNode; onClick?: () => void; secondary?: boolean; className?: string; disabled?: boolean }) => (
  <button onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${secondary ? "border border-slate-200 bg-white text-slate-700 hover:bg-slate-50" : "bg-indigo-600 text-white shadow-lg shadow-indigo-100 hover:bg-indigo-700"} ${className}`}>{children}</button>
);

const Tag = ({ children, color = "indigo" }: { children: ReactNode; color?: "indigo" | "green" | "amber" | "rose" }) => {
  const styles = { indigo: "bg-indigo-50 text-indigo-700", green: "bg-emerald-50 text-emerald-700", amber: "bg-amber-50 text-amber-700", rose: "bg-rose-50 text-rose-700" };
  return <span className={`rounded-lg px-2.5 py-1 text-xs font-bold ${styles[color]}`}>{children}</span>;
};

const Card = ({ children, className = "" }: { children: ReactNode; className?: string }) => <div className={`rounded-2xl border border-slate-200 bg-white ${className}`}>{children}</div>;
const Title = ({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text?: string; action?: ReactNode }) => (
  <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div>{eyebrow && <p className="mb-1 text-sm font-bold text-indigo-600">{eyebrow}</p>}<h1 className="text-3xl font-extrabold tracking-tight">{title}</h1>{text && <p className="mt-2 text-slate-500">{text}</p>}</div>{action}</div>
);

const subjects = [
  { name: "Informatică", streak: 6, score: 84, color: "bg-indigo-600" },
];

function StudentDashboard({ go, codingStreak }: { go: (p: Page) => void; codingStreak: number }) {
  const dashboardSubjects=subjects.map(s=>({...s,streak:codingStreak}));
  return <><Title eyebrow="Luni, 26 mai" title="Bine ai revenit, Alex!" text="Descoperă următoarea activitate potrivită ritmului tău." action={<Button onClick={() => go("practice")}><Icon name="spark" className="size-4"/>Explorează conținut individual</Button>} />
    <div className="mb-8 grid gap-5 xl:grid-cols-[1.5fr_1fr]">
      <div className="rounded-3xl bg-indigo-600 p-7 text-white shadow-xl shadow-indigo-100">
        <div className="mb-6 flex items-center justify-between"><Tag color="amber">SERII ACTIVE</Tag><span className="text-sm text-indigo-200">Regulă: 1 activitate / zi</span></div>
        <div className="grid gap-4 sm:grid-cols-3">{dashboardSubjects.map(s => <button onClick={()=>go("progress")} key={s.name} className="rounded-2xl bg-white/10 p-4 text-left transition hover:bg-white/15"><div className="text-sm font-bold text-indigo-100">{s.name}</div><div className="mt-2 flex items-center gap-2"><Icon name="flame" className="size-6 text-orange-300"/><span className="text-3xl font-black">{s.streak}</span><span className="text-xs text-indigo-200">zile</span></div><p className="mt-2 text-xs text-indigo-200">Teste eligibile din clase + individuale</p></button>)}</div>
      </div>
      <Card className="p-6"><div className="flex justify-between"><div><p className="text-sm font-bold text-slate-500">Obiectiv săptămânal</p><div className="mt-1 text-3xl font-black">4 <span className="text-base text-slate-400">din 6 activități</span></div></div><Tag color="green">+18%</Tag></div><div className="my-5 h-2.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-2/3 bg-emerald-500"/></div><p className="text-sm text-slate-500">Ești peste media clasei. Încă două activități și îți atingi obiectivul.</p></Card>
    </div>
    <SectionTitle title="Recomandate pentru tine" link="Vezi toate testele individuale" onClick={() => go("practice")} />
    <div className="mb-9 grid gap-4 lg:grid-cols-3">{[
      ["Informatică", "Structuri repetitive în Python", "Generat de AI", "10 probleme"],
    ].map((t, i) => <Card key={t[1]} className="group p-5 transition hover:-translate-y-1 hover:shadow-xl"><div className="mb-5 flex justify-between"><Tag color={i === 1 ? "green" : i === 2 ? "amber" : "indigo"}>{t[0]}</Tag><span className="text-xs font-semibold text-slate-400">{t[2]}</span></div><h2 className="text-lg font-extrabold">{t[1]}</h2><p className="mt-1 text-sm text-slate-400">Test individual creat pentru nivelul tău</p><div className="my-5 flex gap-4 border-y border-slate-100 py-3 text-xs font-semibold text-slate-500"><span className="flex gap-1"><Icon name="clock" className="size-4"/>20 min</span><span>{t[3]}</span></div><Button onClick={() => go("quiz")} className="w-full">Începe testul <Icon name="arrow" className="size-4"/></Button></Card>)}</div>
    <SectionTitle title="Materiale individuale recomandate" link="Explorează mai mult" onClick={() => go("library")} />
    <div className="grid gap-4 md:grid-cols-2">{[["spark","Bucle for și while — ghid adaptiv","Informatică · Generat pentru nivelul tău · 7 min"],["play","Cum depanezi un algoritm","Informatică · Video AI personalizat · 9 min"]].map(x=><button onClick={()=>go("library")} key={x[1]} className="flex gap-4 rounded-2xl border border-slate-200 bg-white p-4 text-left transition hover:border-indigo-300 hover:shadow-lg"><span className="grid size-12 shrink-0 place-items-center rounded-xl bg-violet-100 text-violet-700"><Icon name={x[0] as IconName}/></span><span><b className="block">{x[1]}</b><small className="mt-1 block text-slate-500">{x[2]}</small></span></button>)}</div>
  </>;
}

function TeacherDashboard({ go }: { go: (p: Page) => void }) {
  return <><Title eyebrow="Spațiul profesorului" title="Bună dimineața, Andrei!" text="Clasa ta de Informatică a avut 84% activitate în această săptămână." action={<div className="flex gap-2"><Button secondary onClick={() => go("classes")}><Icon name="plus" className="size-4"/>Clasă nouă</Button><Button onClick={() => go("materials")}><Icon name="upload" className="size-4"/>Încarcă material</Button></div>} />
    <div className="mb-8 grid gap-4 md:grid-cols-4">{[["3","clase active"],["83","elevi"],["76%","rată finalizare"],["8,4","scor mediu"]].map(x=><Card key={x[1]} className="p-5"><div className="text-3xl font-black">{x[0]}</div><p className="mt-1 text-sm text-slate-500">{x[1]}</p></Card>)}</div>
    <div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><div><SectionTitle title="Clasa ta" link="Gestionează"/>{["Informatică · X C"].map((c)=><button key={c} onClick={()=>go("class")} className="mb-3 flex w-full items-center gap-4 rounded-2xl border border-slate-200 bg-white p-4 text-left hover:border-indigo-300"><span className="grid size-12 place-items-center rounded-xl bg-indigo-600 font-black text-white">I</span><span className="flex-1"><b className="block">{c}</b><small className="text-slate-400">26 elevi · 1 test AI activ</small></span><span className="text-sm font-bold text-emerald-600">84% activi</span><Icon name="arrow" className="size-4 text-slate-300"/></button>)}</div>
      <div><SectionTitle title="Activitate recentă"/><Card className="divide-y divide-slate-100 px-5">{["Maria a finalizat «Ecuații» · 92%","Testul «Funcții» ajunge la termen azi","12 elevi au deschis materialul AI"].map((x,i)=><div key={x} className="flex gap-3 py-4"><span className={`mt-1 size-2 rounded-full ${i===1?"bg-amber-400":"bg-emerald-500"}`}/><p className="text-sm leading-relaxed text-slate-600">{x}</p></div>)}</Card></div></div>
  </>;
}

function SectionTitle({ title, link, onClick }: { title: string; link?: string; onClick?: () => void }) {
  return <div className="mb-4 flex items-center justify-between"><h2 className="text-xl font-extrabold">{title}</h2>{link&&<button onClick={onClick} className="text-sm font-bold text-indigo-600">{link}</button>}</div>;
}

function Classes({ go, role }: { go:(p:Page)=>void; role:Role }) {
  return <><Title title="Clasele mele" text={role==="teacher"?"Gestionează elevii, anunțurile și testele din fiecare clasă.":"Toate grupurile în care înveți, într-un singur loc."} action={<Button><Icon name="plus" className="size-4"/>{role==="teacher"?"Creează o clasă":"Introdu un cod"}</Button>}/>
    <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{subjects.map((s)=><button onClick={()=>go("class")} key={s.name} className="overflow-hidden rounded-2xl border border-slate-200 bg-white text-left transition hover:-translate-y-1 hover:shadow-xl"><div className={`${s.color} h-28 p-5 text-white`}><span className="text-xs font-bold text-white/70">CLASA A X-A C</span><h2 className="mt-2 text-2xl font-black">{s.name}</h2></div><div className="p-5"><p className="text-sm text-slate-500">Prof. Andrei Pop</p><div className="mt-5 flex justify-between border-t border-slate-100 pt-4 text-sm font-semibold"><span>26 membri</span><span className="text-indigo-600">1 test AI activ</span></div></div></button>)}</div>
  </>;
}

function ClassPage({ go, role }: { go:(p:Page)=>void; role:Role }) {
  const [tab,setTab]=useState("Flux");
  return <><div className="mb-6 rounded-3xl bg-indigo-600 p-7 text-white"><button onClick={()=>go("classes")} className="mb-6 text-sm font-bold text-indigo-200">← Înapoi la clase</button><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="text-sm font-bold text-indigo-200">CLASA A X-A C · COD X7M2Q</p><h1 className="mt-2 text-3xl font-black">Informatică</h1><p className="mt-2 text-indigo-100">Prof. Andrei Pop · 26 elevi</p></div>{role==="teacher"&&<Button onClick={()=>go("builder")} className="bg-white text-indigo-700 shadow-none hover:bg-indigo-50"><Icon name="spark" className="size-4"/>Generează test cu AI</Button>}</div></div>
    <div className="mb-6 flex gap-2 overflow-auto">{["Flux","Teste","Materiale","Progres","Membri"].map((x)=><button onClick={()=>setTab(x)} key={x} className={`rounded-xl px-4 py-2 text-sm font-bold ${tab===x?"bg-slate-900 text-white":"bg-white text-slate-500"}`}>{x}</button>)}</div>
    {tab==="Flux"?<div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><div><Card className="mb-4 p-5"><Tag>NOU</Tag><h2 className="mt-3 text-lg font-extrabold">Recapitulare înainte de test</h2><p className="mt-2 text-sm leading-relaxed text-slate-500">Parcurgeți exercițiile 1–12 din material. Testul va fi disponibil joi la ora 10:00.</p><p className="mt-4 text-xs font-semibold text-slate-400">Publicat de Andrei Pop · acum 2 ore</p></Card><Card className="p-5"><div className="flex justify-between"><Tag color="green">ÎN DESFĂȘURARE</Tag><span className="text-xs font-bold text-rose-600">02:14:36 rămase</span></div><h2 className="mt-3 text-lg font-extrabold">Structuri repetitive în Python</h2><p className="mt-1 text-sm text-slate-500">10 probleme · 10 minute · generat de AI</p><Button onClick={()=>go(role==="teacher"?"statistics":"quiz")} className="mt-5">{role==="teacher"?"Vezi rezultate":"Începe testul"}</Button></Card></div><div>{role==="student"&&<Card className="mb-4 p-5"><p className="text-xs font-bold uppercase text-slate-400">Serie în această clasă</p><div className="mt-3 flex items-center gap-3"><Icon name="flame" className="size-7 text-orange-500"/><b className="text-3xl">4 zile</b></div><p className="mt-2 text-sm text-slate-500">Activitate eligibilă doar din clasa Informatică X B.</p></Card>}<Card className="mb-4 p-5"><div className="flex items-center justify-between"><h2 className="font-extrabold">Limită teste în clasă</h2><Tag color="amber">ACTIVĂ</Tag></div><p className="mt-3 text-sm text-slate-500">Maximum 2 teste pe zi · 26 mai – 9 iunie</p><p className="mt-2 text-xs text-slate-400">Ai folosit 1 din 2 astăzi. Testele individuale rămân nelimitate.</p></Card><Card className="p-5"><h2 className="font-extrabold">Următoarele termene</h2><div className="mt-4 space-y-4">{[["26 MAI","Structuri repetitive în Python"],["30 MAI","Liste și dicționare"]].map(x=><div key={x[1]} className="flex gap-3"><span className="rounded-lg bg-slate-100 p-2 text-center text-xs font-black text-slate-600">{x[0]}</span><span className="text-sm font-semibold">{x[1]}</span></div>)}</div></Card></div></div>:<Card className="p-7"><h2 className="text-xl font-extrabold">{tab} · Informatică X B</h2><p className="mt-2 text-slate-500">{tab==="Teste"?"1 test AI activ, 4 finalizate și istoricul rezultatelor clasei.":tab==="Materiale"?"1 material original + 2 versiuni AI pentru această clasă.":tab==="Progres"?"Progresul, activitatea și istoricul tău exclusiv în această clasă.":"28 de membri înscriși în această clasă."}</p><Button onClick={()=>tab==="Teste"?go("quiz"):tab==="Progres"&&role==="teacher"?go("statistics"):undefined} className="mt-5">{tab==="Teste"?"Deschide testele":tab==="Progres"?"Vezi detalii":"Explorează"}</Button></Card>}
  </>;
}

function Practice({ go }: { go:(p:Page)=>void }) {
  const [query,setQuery]=useState(""); const [difficulty,setDifficulty]=useState("Toate");
  const items=[["Informatică","Structuri repetitive în Python","Mediu","10 probleme"]];
  const visible=items.filter(x=>(x[0]+" "+x[1]).toLowerCase().includes(query.toLowerCase())&&(difficulty==="Toate"||x[2]===difficulty));
  return <><Title title="Teste individuale" text="Exersează fără limită zilnică. Testele AI individuale nu influențează limita clasei."/><div className="mb-6 flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Icon name="search" className="absolute left-3 top-3 size-5 text-slate-400"/><input value={query} onChange={e=>setQuery(e.target.value)} className="w-full rounded-xl border border-slate-200 bg-white py-3 pl-11 pr-4 outline-none focus:border-indigo-400" placeholder="Caută după subiect..."/></div><select value={difficulty} onChange={e=>setDifficulty(e.target.value)} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-600"><option>Toate</option><option>Ușor</option><option>Mediu</option><option>Avansat</option></select></div>
    {visible.length?<div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{visible.map((x,i)=><Card key={x[1]} className="p-5"><div className="flex justify-between"><Tag color={i%3===1?"green":i%3===2?"amber":"indigo"}>{x[0]}</Tag><span className="text-xs font-bold text-slate-400">{x[2]}</span></div><h2 className="mt-5 text-lg font-extrabold">{x[1]}</h2><p className="mt-2 text-sm text-slate-500">{x[3]} · aproximativ 20 min</p><Button secondary onClick={()=>go("quiz")} className="mt-5 w-full">Începe testul individual</Button></Card>)}</div>:<Card className="p-10 text-center"><h2 className="font-extrabold">Nu am găsit teste</h2><p className="mt-2 text-sm text-slate-500">Încearcă alt subiect sau elimină filtrul.</p><Button secondary onClick={()=>{setQuery("");setDifficulty("Toate")}} className="mt-4">Resetează filtrele</Button></Card>}
  </>;
}

function Library({ go }: { go:(p:Page)=>void }) {
  const [topic,setTopic]=useState("Pentru tine");
  const [opened,setOpened]=useState("");
  const courses=[["AI personalizat","Bucle for și while — ghid adaptiv","Exemple adaptate nivelului Intermediar și dificultăților tale · 7 min","spark"],["AI personalizat","Depanarea algoritmilor pas cu pas","Lecție video recomandată după ultimele răspunsuri · 9 min","play"]];
  return <><Title eyebrow="Informatică · independent de clase" title="Materiale individuale" text="Exclusiv materiale generate de agentul AI pentru nivelul, rezultatele și obiectivele tale."/><div className="mb-6 flex gap-2"><button onClick={()=>setTopic("Pentru tine")} className={`rounded-xl px-4 py-2.5 text-sm font-bold ${topic==="Pentru tine"?"bg-indigo-600 text-white":"bg-white text-slate-600"}`}>Pentru tine</button><button onClick={()=>setTopic("Informatică")} className={`rounded-xl px-4 py-2.5 text-sm font-bold ${topic==="Informatică"?"bg-indigo-600 text-white":"bg-white text-slate-600"}`}>Informatică · Intermediar</button></div>
    <div className="grid gap-5 md:grid-cols-3">{courses.map((x,i)=><Card key={x[1]} className="p-5"><span className={`grid size-12 place-items-center rounded-xl ${i?"bg-violet-100 text-violet-700":"bg-indigo-50 text-indigo-700"}`}><Icon name={x[3] as IconName}/></span><Tag color={i?"indigo":"green"}>{x[0]}</Tag><h2 className="mt-4 text-lg font-extrabold">{x[1]}</h2><p className="mt-2 min-h-12 text-sm leading-relaxed text-slate-500">{x[2]}</p><Button secondary onClick={()=>setOpened(x[1])} className="mt-5 w-full">{opened===x[1]?"Material deschis":"Deschide cursul"}</Button></Card>)}</div>
    {opened&&<Card className="mt-6 p-6"><div className="flex justify-between gap-4"><div><Tag color="green">PREVIZUALIZARE</Tag><h2 className="mt-3 text-xl font-extrabold">{opened}</h2><p className="mt-2 text-sm text-slate-500">Versiune demonstrativă. Conținutul AI adaptează explicațiile și exemplele pe baza rezultatelor tale recente.</p></div><button onClick={()=>setOpened("")} className="text-sm font-bold text-slate-500">Închide</button></div><Button onClick={()=>go("practice")} className="mt-5">Testează ce ai învățat</Button></Card>}
  </>;
}

function Progress() {
  const [feedback,setFeedback]=useState(""); const [sent,setSent]=useState(false);
  return <><Title title="Progresul meu" text="Indicatori măsurabili pentru obiectivul tău de Informatică."/>
    <div className="mb-6 grid gap-4 md:grid-cols-4"><Card className="p-5"><p className="text-sm font-bold text-slate-500">Timp ultimul test</p><b className="mt-2 block text-3xl">8m 42s</b><p className="mt-2 text-xs text-emerald-600">cu 1m 18s mai rapid</p></Card><Card className="p-5"><p className="text-sm font-bold text-slate-500">Probleme rezolvate</p><b className="mt-2 block text-3xl">48</b><p className="mt-2 text-xs text-slate-500">22 ușoare · 19 medii · 7 dificile</p></Card><Card className="p-5"><p className="text-sm font-bold text-slate-500">Scor mediu</p><b className="mt-2 block text-3xl">84%</b><p className="mt-2 text-xs text-emerald-600">+6% în ultimele 14 zile</p></Card><Card className="p-5"><p className="text-sm font-bold text-slate-500">Estimare AI</p><b className="mt-2 block text-3xl">9 zile</b><p className="mt-2 text-xs text-slate-500">până la atingerea obiectivului</p></Card></div>
    <div className="mb-6 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><Card className="p-6"><div className="flex justify-between"><div><h2 className="font-extrabold">Obiectiv: stăpânirea structurilor repetitive</h2><p className="mt-1 text-sm text-slate-500">Bazat pe 4 activități pe săptămână</p></div><b className="text-2xl text-indigo-600">68%</b></div><div className="my-6 h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-2/3 rounded-full bg-indigo-600"/></div><div className="grid grid-cols-3 gap-3 text-center text-sm"><span className="rounded-xl bg-slate-50 p-3"><b className="block">100%</b>noțiuni de bază</span><span className="rounded-xl bg-slate-50 p-3"><b className="block">72%</b>bucle simple</span><span className="rounded-xl bg-slate-50 p-3"><b className="block">34%</b>bucle imbricate</span></div></Card><Card className="p-6"><h2 className="font-extrabold">Dificultăți identificate de AI</h2>{[["Condiții de oprire",42],["Bucle imbricate",35],["Răspunsuri explicative",28]].map(x=><div key={x[0]} className="mt-5"><div className="mb-2 flex justify-between text-sm"><b>{x[0]}</b><span className="text-rose-600">{x[1]}% erori</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-rose-500" style={{width:`${x[1]}%`}}/></div></div>)}</Card></div>
    <Card className="mb-6 p-6"><h2 className="font-extrabold">Evoluția timpului de rezolvare</h2><p className="mt-1 text-sm text-slate-500">Ultimele 5 teste: 14m → 12m → 11m → 10m → 8m 42s</p><div className="mt-6 flex h-32 items-end gap-4">{[100,82,74,66,57].map((h,i)=><div key={i} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-lg bg-violet-500" style={{height:`${h}%`}}/><small className="text-slate-400">T{i+1}</small></div>)}</div></Card>
    <div className="mb-6 grid gap-6 xl:grid-cols-2"><Card className="p-6"><div className="flex items-center gap-2 text-indigo-600"><Icon name="spark"/><b>Feedback de la agentul AI</b></div><h2 className="mt-4 text-xl font-extrabold">Progresezi constant la algoritmi</h2><p className="mt-3 text-sm leading-relaxed text-slate-600">Punctul tău forte este urmărirea execuției pas cu pas. Încă apar erori când alegi condiția de oprire pentru bucle, iar răspunsurile scrise pot fi mai precise.</p><div className="mt-4 rounded-xl bg-indigo-50 p-4 text-sm text-indigo-700"><b>Următorii pași:</b> rezolvă ghidul despre `break`, apoi două probleme cu bucle while. Feedback actualizat astăzi, după ultimul test.</div></Card><Card className="p-6"><h2 className="font-extrabold">Spune-i agentului ce te-ar ajuta</h2><p className="mt-1 text-sm text-slate-500">Răspunsul tău va adapta explicațiile și exercițiile viitoare.</p><textarea value={feedback} onChange={e=>{setFeedback(e.target.value);setSent(false)}} className="mt-4 min-h-28 w-full rounded-xl border border-slate-200 p-3" placeholder="Ex: Aș prefera mai multe exemple de cod explicate pas cu pas..."/>{sent?<p className="mt-3 rounded-xl bg-emerald-50 p-3 text-sm font-bold text-emerald-700"><Icon name="check" className="mr-2 inline size-4"/>Feedback trimis. Recomandările viitoare vor ține cont de el.</p>:<Button onClick={()=>feedback.trim()&&setSent(true)} className="mt-3">Trimite feedback</Button>}</Card></div>
    <Card className="mb-6 p-6"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div><p className="text-sm font-bold text-indigo-600">NIVELUL MEU</p><h2 className="mt-1 text-3xl font-black">Intermediar</h2><p className="mt-2 text-sm text-slate-500">Următorul statut: <b>Elev de 10</b></p></div><Tag color="amber">Estimare AI: 3–4 săptămâni</Tag></div><div className="my-6 h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-3/5 rounded-full bg-indigo-600"/></div><div className="grid gap-4 md:grid-cols-2"><div className="rounded-xl bg-emerald-50 p-4"><b className="text-emerald-700">Competențe dobândite</b><p className="mt-2 text-sm text-slate-600">Variabile, condiții, bucle simple și trasarea execuției.</p></div><div className="rounded-xl bg-amber-50 p-4"><b className="text-amber-700">Pentru a avansa</b><p className="mt-2 text-sm text-slate-600">Bucle imbricate, cod fără erori și explicații mai riguroase.</p></div></div><div className="mt-5 flex flex-wrap gap-2">{["Începător","Intermediar","Elev de 10","Olimpic"].map((x,i)=><span key={x} className={`rounded-full px-3 py-1.5 text-xs font-bold ${i<=1?"bg-indigo-600 text-white":"bg-slate-100 text-slate-400"}`}>{x}</span>)}</div></Card>
    <Card className="p-6"><div className="flex justify-between"><div><p className="text-sm font-bold text-slate-500">Punctele mele</p><h2 className="mt-1 text-3xl font-black">1.280 XP</h2></div><Tag color="green">+145 săptămâna aceasta</Tag></div><div className="mt-5 divide-y divide-slate-100">{[["Test explicativ finalizat","+120 XP","100 bază + 10 streak + 10 milestone"],["Curs AI finalizat","+25 XP","25 puncte curs"]].map(x=><div key={x[0]} className="flex items-center gap-3 py-3"><span className="flex-1"><b className="block text-sm">{x[0]}</b><small className="text-slate-400">{x[2]}</small></span><b className="text-emerald-600">{x[1]}</b></div>)}</div></Card>
  </>;
}

function Builder({ go }: { go:(p:Page)=>void }) {
  const [generated,setGenerated]=useState(false);
  const [contentType,setContentType]=useState("Test explicativ");
  return <><Title eyebrow="Agent AI pentru clasă" title="Generează conținut din sursele tale" text="Conținutul aprobat rămâne disponibil exclusiv clasei selectate." action={generated?<Button onClick={()=>go("class")}>Aprobă și distribuie în clasă</Button>:undefined}/><div className="grid gap-6 xl:grid-cols-[1.4fr_1fr]"><Card className="p-6"><h2 className="text-lg font-extrabold">1. Sursă și conținut</h2><label className="mt-5 block text-sm font-bold">Material din „Materialele mele”<select className="mt-2 w-full rounded-xl border border-slate-200 p-3"><option>Bazele programării în Python.pdf</option></select></label><label className="mt-4 block text-sm font-bold">Tip conținut<select value={contentType} onChange={e=>{setContentType(e.target.value);setGenerated(false)}} className="mt-2 w-full rounded-xl border border-slate-200 p-3"><option>Curs explicativ</option><option>Videoclip educațional</option><option>Test explicativ</option><option>Exerciții practice</option></select></label><label className="mt-4 block text-sm font-bold">Temă<input value="Structuri repetitive în Python" readOnly className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">Structură<select className="mt-2 w-full rounded-xl border border-slate-200 p-3"><option>10 probleme: 5 grilă + 5 scrise</option></select></label><label className="text-sm font-bold">Nivel<select className="mt-2 w-full rounded-xl border border-slate-200 p-3"><option>Intermediar</option><option>Începător</option><option>Avansat</option></select></label></div><Button onClick={()=>setGenerated(true)} className="mt-6 w-full"><Icon name="spark" className="size-4"/>Generează cu agentul AI</Button></Card><Card className="p-6"><h2 className="font-extrabold">2. Interval și recompense</h2><label className="mt-5 block text-sm font-bold">Începe la<input type="datetime-local" defaultValue="2025-05-26T09:00" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><label className="mt-4 block text-sm font-bold">Se închide exact la<input type="datetime-local" defaultValue="2025-05-26T12:30" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><p className="mt-2 text-xs text-slate-500">Intervalele mai scurte de 24h sunt permise. După închidere, trimiterea este blocată.</p><div className="mt-5 grid grid-cols-2 gap-3"><label className="text-sm font-bold">Puncte de bază<input type="number" defaultValue="100" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><label className="text-sm font-bold">Multiplicator streak<input type="number" step="0.1" defaultValue="1.2" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><label className="text-sm font-bold">Bonus milestone<input type="number" defaultValue="25" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><label className="text-sm font-bold">Prag recompensă<input type="number" defaultValue="500" className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label></div></Card></div>{generated&&<Card className="mt-6 p-6"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><Tag color="green">PREVIZUALIZARE GENERATĂ</Tag><h2 className="mt-3 text-xl font-extrabold">{contentType}: Structuri repetitive</h2><p className="mt-1 text-sm text-slate-500">Sursă verificabilă · nivel Intermediar · exclusiv Informatică X C</p></div><Button secondary onClick={()=>contentType==="Test explicativ"?go("quiz"):go("class")}>Previzualizează și verifică</Button></div></Card>}
  </>;
}

function Quiz({ go, complete }: { go:(p:Page)=>void; complete:()=>void }) {
  const [question,setQuestion]=useState(0); const [selected,setSelected]=useState<number|null>(null); const [written,setWritten]=useState("");
  const data=[
    {q:"Ce valori afișează: for i in range(1, 4): print(i)?",a:["1, 2, 3","1, 2, 3, 4","0, 1, 2, 3","0, 1, 2"]},
    {q:"Ce instrucțiune oprește imediat execuția unei bucle?",a:["stop","exit","break","return loop"]},
    {q:"Care este rezultatul expresiei len([4, 8, 15])?",a:["2","3","4","15"]},
    {q:"Ce tip de date folosește perechi cheie–valoare?",a:["list","tuple","dict","set"]},
    {q:"Care operator verifică egalitatea în Python?",a:["=","==","!=","==="]},
    {q:"Completează secvența pentru a afișa numerele 0–4: for i in _____: print(i)",a:null},
    {q:"Identifică și corectează eroarea: if nota >= 5 print('Promovat')",a:null},
    {q:"Scrie instrucțiunea lipsă pentru a adăuga valoarea 7 în lista valori.",a:null},
    {q:"Completează condiția unei bucle care citește numere până când utilizatorul introduce 0.",a:null},
    {q:"Explică printr-un exemplu real când ai folosi while în loc de for.",a:null},
  ];
  const next=()=>{if(question<9){setQuestion(q=>q+1);setSelected(null);setWritten("")}else{complete();go("results")}};
  const canContinue=data[question].a?selected!==null:written.trim().length>2;
  return <><div className="mb-6 flex items-center justify-between"><button onClick={()=>go("practice")} className="text-sm font-bold text-slate-500">Închide testul</button><div className="text-sm font-bold">Problema {question+1} din 10</div><Tag color="amber"><Icon name="spark" className="mr-1 inline size-4"/>ADAPTAT NIVELULUI TĂU</Tag></div><div className="mb-8 h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full bg-indigo-600 transition-all" style={{width:`${(question+1)*10}%`}}/></div><Card className="mx-auto max-w-3xl p-6 md:p-9"><Tag>INFORMATICĂ · {question>=5?"RĂSPUNS SCRIS":"ALEGERE MULTIPLĂ"}</Tag><h1 className="mt-5 text-2xl font-extrabold leading-snug">{data[question].q}</h1>{data[question].a?<div className="mt-7 space-y-3">{data[question].a.map((a,i)=><button onClick={()=>setSelected(i)} key={a} className={`flex w-full items-center gap-4 rounded-xl border p-4 text-left font-semibold transition ${selected===i?"border-indigo-500 bg-indigo-50 text-indigo-800":"border-slate-200 hover:border-indigo-300"}`}><span className={`grid size-8 shrink-0 place-items-center rounded-full ${selected===i?"bg-indigo-600 text-white":"bg-slate-100 text-slate-500"}`}>{String.fromCharCode(65+i)}</span>{a}</button>)}</div>:<textarea value={written} onChange={e=>setWritten(e.target.value)} className="mt-7 min-h-40 w-full rounded-xl border border-slate-200 p-4 font-mono outline-none focus:border-indigo-500" placeholder="Scrie sau completează secvența de cod..."/>}<div className="mt-8 flex justify-between"><Button secondary onClick={()=>question?setQuestion(q=>q-1):go("practice")}>Înapoi</Button><Button disabled={!canContinue} onClick={next}>{question===9?"Trimite testul":"Următoarea"} <Icon name="arrow" className="size-4"/></Button></div></Card></>;
}

function Results({ go }: { go:(p:Page)=>void }) {
  return <><div className="mx-auto max-w-4xl"><div className="mb-6 rounded-3xl bg-slate-900 p-8 text-center text-white"><div className="mx-auto grid size-16 place-items-center rounded-full bg-emerald-500"><Icon name="check" className="size-8"/></div><p className="mt-4 text-sm font-bold text-slate-400">TEST EXPLICATIV FINALIZAT</p><h1 className="mt-2 text-3xl font-black">Scor: 8 din 10 · 80%</h1><p className="mt-2 text-slate-300">5 grilă + 5 răspunsuri scrise · timp 18m 42s</p><div className="mx-auto mt-5 max-w-md rounded-xl bg-white/10 p-3 text-sm"><b>120 puncte:</b> 100 bază + 10 streak × 1,0 + 10 milestone</div><div className="mt-6 flex justify-center gap-3"><Button secondary onClick={()=>go("progress")}>Vezi progresul</Button><Button onClick={()=>go("practice")}>Alt test individual</Button></div></div>
    <SectionTitle title="Analiza celor 10 răspunsuri"/><Card className="mb-4 p-6"><div className="flex gap-3"><span className="grid size-8 place-items-center rounded-full bg-emerald-100 text-emerald-700"><Icon name="check" className="size-4"/></span><div><p className="text-xs font-bold text-slate-400">PROBLEMA 1 · CORECT</p><h2 className="mt-1 font-extrabold">range(1, 4) afișează 1, 2, 3</h2><p className="mt-2 text-sm text-slate-500">Limita superioară din range nu este inclusă.</p></div></div></Card>
    <Card className="mb-4 p-6"><div className="flex gap-3"><span className="grid size-8 place-items-center rounded-full bg-rose-100 font-black text-rose-700">×</span><div className="flex-1"><p className="text-xs font-bold text-slate-400">PROBLEMA 2 · INCORECT</p><h2 className="mt-1 font-extrabold">Instrucțiunea care oprește bucla</h2><p className="mt-2 text-sm text-rose-700">Răspunsul tău: exit</p><p className="mt-1 text-sm text-emerald-700">Corect: break</p><div className="mt-4 rounded-xl bg-violet-50 p-4"><p className="flex items-center gap-2 text-sm font-bold text-violet-800"><Icon name="spark" className="size-4"/>Explicație personalizată AI</p><p className="mt-2 text-sm leading-relaxed text-violet-700">`break` încheie doar bucla curentă, iar programul continuă cu instrucțiunea următoare. `exit` încheie întregul program.</p><button onClick={()=>go("library")} className="mt-3 text-sm font-bold text-violet-800">Deschide materialul recomandat →</button></div></div></div></Card><Card className="p-6"><p className="text-xs font-bold text-slate-400">PROBLEMA 10 · RĂSPUNS SCRIS ACCEPTAT</p><h2 className="mt-1 font-extrabold">Când folosim while în loc de for?</h2><p className="mt-2 text-sm text-emerald-700">Ideea principală este corectă: while este util când numărul repetărilor nu este cunoscut dinainte.</p></Card></div></>;
}

