function StudentProfile({ go }: { go:(p:Page)=>void }) {
  return <><button onClick={()=>go("statistics")} className="mb-5 text-sm font-bold text-slate-500">← Înapoi la statisticile clasei</button><div className="mb-6 flex flex-col gap-4 rounded-3xl bg-indigo-600 p-7 text-white md:flex-row md:items-center"><span className="grid size-16 place-items-center rounded-2xl bg-white/15 text-xl font-black">AM</span><div className="flex-1"><h1 className="text-2xl font-black">Alex Munteanu</h1><p className="text-indigo-100">Clasa a X-a B · activ acum 2 ore</p></div><div className="flex gap-6"><span><b className="block text-2xl">8,5</b><small className="text-indigo-200">medie</small></span><span><b className="block text-2xl">12</b><small className="text-indigo-200">zile streak</small></span></div></div>
    <div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><div><SectionTitle title="Istoric evaluări"/>{[["Structuri repetitive în Python","67%","Astăzi"]].map(x=><Card key={x[0]} className="mb-3 flex items-center p-4"><span className="flex-1"><b className="block">{x[0]}</b><small className="text-slate-400">{x[2]} · test generat de AI · 10 probleme</small></span><b className="text-xl text-indigo-600">{x[1]}</b></Card>)}</div><div><Card className="mb-5 p-5"><h2 className="font-extrabold">Zone care necesită sprijin</h2><div className="mt-4 space-y-3"><Tag color="rose">Condiții de oprire</Tag><Tag color="amber">Explicarea algoritmului</Tag></div><p className="mt-4 text-sm leading-relaxed text-slate-500">Alex ar beneficia de exemple vizuale suplimentare despre controlul buclelor.</p><Button className="mt-4 w-full"><Icon name="book" className="size-4"/>Recomandă materialul AI</Button></Card><Card className="p-5"><h2 className="font-extrabold">Activitate</h2>{subjects.map(s=><div key={s.name} className="mt-4 flex items-center gap-3"><span className={`size-3 rounded-full ${s.color}`}/><span className="flex-1 text-sm font-semibold">{s.name}</span><span className="text-sm text-slate-500">{s.streak} zile</span></div>)}</Card></div></div>
  </>;
}

function Auth({ go, setRole, dark, toggleTheme }: { go:(p:Page)=>void; setRole:(r:Role)=>void; dark:boolean; toggleTheme:()=>void }) {
  const [register,setRegister]=useState(()=>new URLSearchParams(window.location.search).get("mode")==="register"); const [choice,setChoice]=useState<Role>("student");
  const enter=()=>{setRole(choice);go("dashboard")};
  return <div className={`theme-shell ${dark?"theme-dark":"theme-light"} grid min-h-screen lg:grid-cols-2`}><button onClick={toggleTheme} aria-label="Schimbă tema" className="fixed right-5 top-5 z-10 rounded-xl border border-slate-200 bg-white p-3 text-slate-600 shadow"><Icon name={dark?"sun":"moon"}/></button><div className="hidden bg-indigo-600 p-12 text-white lg:flex lg:flex-col lg:justify-between"><div className="flex items-center gap-3 text-2xl font-black"><span className="grid size-11 place-items-center rounded-xl bg-white text-indigo-600"><Icon name="classes"/></span>Nexora</div><div><Tag color="amber">ÎNVAȚĂ CU ÎNCREDERE</Tag><h1 className="mt-6 max-w-lg text-5xl font-black leading-tight">Un spațiu de învățare construit în jurul progresului.</h1><p className="mt-5 max-w-md text-lg text-indigo-100">Clase, evaluări, resurse și explicații AI într-o experiență coerentă.</p></div><p className="text-sm text-indigo-200">Creat pentru profesori și elevi din România.</p></div><div className="flex items-center justify-center bg-white p-6"><div className="w-full max-w-lg"><p className="text-sm font-bold text-indigo-600">{register?"CREEAZĂ CONT":"BINE AI VENIT"}</p><h1 className="mt-2 text-3xl font-black">{register?"Cum vei folosi Nexora?":"Autentifică-te în cont"}</h1><p className="mt-2 text-slate-500">{register?"Alege tipul de cont. Îl poți administra ulterior din setări.":"Continuă progresul de unde ai rămas."}</p>{register&&<div className="mt-7 grid gap-3 sm:grid-cols-2">{[["teacher","Cont profesor","Creează clase, materiale și teste. Monitorizează progresul."],["student","Cont elev","Alătură-te claselor, învață și urmărește-ți progresul."]].map(x=><button key={x[0]} onClick={()=>setChoice(x[0] as Role)} className={`rounded-2xl border-2 p-5 text-left transition ${choice===x[0]?"border-indigo-600 bg-indigo-50":"border-slate-200 hover:border-slate-300"}`}><span className={`grid size-10 place-items-center rounded-xl ${choice===x[0]?"bg-indigo-600 text-white":"bg-slate-100 text-slate-500"}`}><Icon name={x[0]==="teacher"?"book":"users"}/></span><b className="mt-4 block">{x[1]}</b><small className="mt-1 block leading-relaxed text-slate-500">{x[2]}</small></button>)}</div>}<div className="mt-7 space-y-4"><label className="block text-sm font-bold">Adresă de email<input type="email" placeholder="nume@exemplu.ro" className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 outline-none focus:border-indigo-500"/></label><label className="block text-sm font-bold">Parolă<input type="password" placeholder="••••••••" className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 outline-none focus:border-indigo-500"/></label><Button onClick={enter} className="w-full py-3">{register?"Creează contul":"Autentifică-te"}</Button><button onClick={()=>setRegister(!register)} className="w-full text-center text-sm font-bold text-indigo-600">{register?"Ai deja cont? Autentifică-te":"Nu ai cont? Creează unul gratuit"}</button></div></div></div></div>;
}

export default function App() {
  const query=new URLSearchParams(window.location.search);
  const [page,setPage]=useState<Page>(()=>(query.get("page") as Page)||"dashboard");
  const [role,setRole]=useState<Role>(()=>query.get("role")==="teacher"?"teacher":"student");
  const [mobile,setMobile]=useState(false);
  const [dark,setDark]=useState(false);
  const [codingStreak,setCodingStreak]=useState(5);
  if(page==="auth") return <Auth go={setPage} setRole={setRole} dark={dark} toggleTheme={()=>setDark(!dark)}/>;
  const studentNav = [{p:"dashboard",l:"Panou principal",i:"home"},{p:"classes",l:"Clasele mele",i:"classes"},{p:"practice",l:"Teste individuale",i:"tests"},{p:"library",l:"Materiale individuale",i:"book"},{p:"progress",l:"Progresul meu",i:"chart"}];
  const teacherNav = [{p:"dashboard",l:"Panou principal",i:"home"},{p:"classes",l:"Clasele mele",i:"classes"},{p:"materials",l:"Materialele mele",i:"book"},{p:"test-management",l:"Teste generate AI",i:"tests"},{p:"statistics",l:"Statistici clase",i:"chart"}];
  const nav = (role==="student"?studentNav:teacherNav) as {p:Page,l:string,i:IconName}[];
  const content = page==="dashboard"?(role==="student"?<StudentDashboard go={setPage} codingStreak={codingStreak}/>:<TeacherDashboard go={setPage}/>):page==="classes"?<Classes go={setPage} role={role}/>:page==="class"?<ClassPage go={setPage} role={role}/>:page==="practice"?<Practice go={setPage}/>:page==="library"?<Library go={setPage}/>:page==="progress"?<Progress/>:page==="materials"?<TeacherMaterials/>:page==="test-management"?<TestManagement go={setPage}/>:page==="statistics"?<ClassStatistics go={setPage}/>:page==="student"?<StudentProfile go={setPage}/>:page==="builder"?<Builder go={setPage}/>:page==="quiz"?<Quiz go={setPage} complete={()=>setCodingStreak(s=>s+1)}/>:<Results go={setPage}/>;
  return <div className={`theme-shell ${dark?"theme-dark":"theme-light"} min-h-screen bg-slate-50 text-slate-900`}><aside className={`fixed inset-y-0 left-0 z-30 w-64 border-r border-slate-200 bg-white p-4 transition-transform lg:translate-x-0 ${mobile?"translate-x-0":"-translate-x-full"}`}><button onClick={()=>setPage("dashboard")} className="mb-9 flex items-center gap-3 px-2 py-2 text-left"><span className="brand-mark grid size-10 place-items-center rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-200"><Icon name="spark"/></span><span><b className="block text-xl tracking-tight">Nexora</b><small className="font-bold uppercase tracking-widest text-slate-400">Learn with clarity</small></span></button><nav className="space-y-1">{nav.map(n=><button key={n.p} onClick={()=>{setPage(n.p);setMobile(false)}} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold ${page===n.p?"bg-indigo-50 text-indigo-700":"text-slate-500 hover:bg-slate-50"}`}><Icon name={n.i}/>{n.l}</button>)}</nav><div className="absolute inset-x-4 bottom-4"><button onClick={()=>setPage("auth")} className="w-full text-center text-xs font-bold text-slate-400 hover:text-slate-700">Deconectare</button></div></aside>{mobile&&<button onClick={()=>setMobile(false)} className="fixed inset-0 z-20 bg-slate-900/30 lg:hidden"/>}<main className="lg:pl-64"><header className="sticky top-0 z-10 flex h-20 items-center justify-between border-b border-slate-200/80 bg-white/90 px-5 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button onClick={()=>setMobile(true)} className="rounded-lg p-2 lg:hidden"><Icon name="menu"/></button><div className="relative hidden sm:block"><Icon name="search" className="absolute left-3 top-2.5 size-5 text-slate-400"/><input className="w-60 rounded-xl border border-slate-200 bg-slate-50 py-2.5 pl-10 pr-3 text-sm outline-none" placeholder="Caută în Nexora..."/></div></div><div className="flex items-center gap-2"><button onClick={()=>setDark(!dark)} aria-label="Schimbă tema" className="rounded-xl border border-slate-200 p-2.5 text-slate-500 transition hover:bg-slate-50"><Icon name={dark?"sun":"moon"}/></button><button className="relative rounded-xl border border-slate-200 p-2.5 text-slate-500"><Icon name="bell"/><span className="absolute right-2 top-2 size-2 rounded-full bg-rose-500"/></button><button onClick={()=>setPage("auth")} className="ml-1 flex items-center gap-3 rounded-xl p-1 text-left"><div className="grid size-10 place-items-center rounded-xl bg-indigo-100 text-sm font-black text-indigo-700">{role==="student"?"AM":"AP"}</div><div className="hidden sm:block"><b className="block text-sm">{role==="student"?"Alex Munteanu":"Andrei Pop"}</b><small className="text-slate-400">{role==="student"?"Elev":"Profesor"}</small></div></button></div></header><div className="mx-auto max-w-screen-xl px-5 py-8 md:px-8 lg:px-10">{content}</div></main></div>;
}
